import { supabase } from '@/lib/supabase';
import type { CeoPlan } from './schemas';

export interface CeoPlanRecord {
  id: string;
  org_id: string;
  command: string;
  plan: CeoPlan;
  status: 'draft' | 'approved' | 'done';
  created_at: string;
}

/**
 * Fetches all past strategic plans generated by the AI CEO for the workspace.
 */
export async function fetchCeoPlans(orgId: string): Promise<CeoPlanRecord[]> {
  const { data, error } = await supabase
    .from('ceo_plans')
    .select('*')
    .eq('org_id', orgId)
    .order('created_at', { ascending: false });

  if (error) {
    throw new Error(error.message);
  }

  const rawRows = data ?? [];
  return rawRows.map((row) => ({
    id: row.id,
    org_id: row.org_id,
    command: row.command,
    plan: row.plan as unknown as CeoPlan,
    status: row.status as 'draft' | 'approved' | 'done',
    created_at: row.created_at,
  }));
}

/**
 * Fetches a single CEO plan by ID.
 */
export async function fetchCeoPlanById(
  id: string,
  orgId: string,
): Promise<CeoPlanRecord | null> {
  const { data, error } = await supabase
    .from('ceo_plans')
    .select('*')
    .eq('id', id)
    .eq('org_id', orgId)
    .maybeSingle();

  if (error) {
    throw new Error(error.message);
  }

  if (!data) return null;

  return {
    id: data.id,
    org_id: data.org_id,
    command: data.command,
    plan: data.plan as unknown as CeoPlan,
    status: data.status as 'draft' | 'approved' | 'done',
    created_at: data.created_at,
  };
}

/**
 * Updates plan status (e.g. from 'draft' to 'approved' or 'done').
 */
export async function updateCeoPlanStatus(
  id: string,
  orgId: string,
  status: 'draft' | 'approved' | 'done',
): Promise<CeoPlanRecord> {
  const { data, error } = await supabase
    .from('ceo_plans')
    .update({ status })
    .eq('id', id)
    .eq('org_id', orgId)
    .select()
    .single();

  if (error) {
    throw new Error(error.message);
  }

  return {
    id: data.id,
    org_id: data.org_id,
    command: data.command,
    plan: data.plan as unknown as CeoPlan,
    status: data.status as 'draft' | 'approved' | 'done',
    created_at: data.created_at,
  };
}

